import local.thor.bilichannels.*;import org.json.*;
public class CreatorShortcutTest {
 static int checks;static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{
  check(ShortcutBindings.valid("unknown",0).equals("danmaku")&&ShortcutBindings.valid("",1).equals("mute"),"fallback defaults");
  ShortcutBindings triggers=new ShortcutBindings();check(triggers.edge(0,false,true),"first digital down fires");check(!triggers.edge(0,false,true),"autorepeat suppressed");check(!triggers.edge(0,true,true),"analog duplicate suppressed");check(!triggers.edge(0,false,false)&&!triggers.edge(0,true,false),"release silent");check(triggers.edge(0,true,true)&&!triggers.edge(0,false,true),"analog first suppresses digital duplicate");check(triggers.edge(1,true,true),"triggers independent");triggers.reset();check(triggers.edge(0,false,true),"resume clears held state");
  JSONObject video=new JSONObject().put("bvid","BV1234567890").put("title","test").put("length","12:34").put("author","UP").put("mid",123).put("pic","//cdn.test/a.jpg");Video parsed=ApiModels.video(video);check(parsed.upMid==123&&parsed.duration==754&&parsed.cover.startsWith("https://"),"space video duration and owner identity");
  JSONObject page=new JSONObject().put("list",new JSONObject().put("vlist",new JSONArray().put(video))).put("page",new JSONObject().put("pn",1).put("ps",30).put("count",31));FeedPager.Page first=CreatorModels.videos(page,1,123,"UP","https://cdn.test/avatar");check(first.more&&first.items.get(0).upAvatar.contains("avatar"),"space first page and avatar");page.getJSONObject("page").put("pn",2);check(!CreatorModels.videos(page,2,123,"UP","").more,"space server total ends pages");boolean bad=false;try{CreatorModels.videos(page,1,123,"UP","");}catch(Exception e){bad=true;}check(bad,"wrong creator page rejected");
  JSONObject author=new JSONObject().put("mid",123).put("name","UP").put("face","//cdn.test/avatar").put("pub_time","昨天");JSONObject dynamic=new JSONObject().put("desc",new JSONObject().put("text","hello\nworld")).put("major",new JSONObject().put("draw",new JSONObject().put("items",new JSONArray().put(new JSONObject().put("src","//cdn.test/image")))));JSONObject row=new JSONObject().put("id_str","1").put("modules",new JSONObject().put("module_author",author).put("module_dynamic",dynamic));JSONObject data=new JSONObject().put("items",new JSONArray().put(row).put(row)).put("has_more",true).put("offset","next");CreatorModels.Page posts=CreatorModels.dynamics(data,"");check(posts.rows.size()==1&&posts.more,"dynamic ids deduplicated and cursor followed");check(posts.rows.get(0).text.equals("hello\nworld")&&posts.rows.get(0).images.get(0).startsWith("https://")&&posts.rows.get(0).time.equals("昨天"),"text and image dynamic retained");
  JSONObject shared=new JSONObject(row.toString()).put("id_str","2");shared.getJSONObject("modules").getJSONObject("module_dynamic").put("major",new JSONObject().put("archive",video));data.put("items",new JSONArray().put(shared)).put("has_more",false);check(CreatorModels.dynamics(data,"").rows.get(0).video.upMid==123,"video dynamic is playable with creator identity");
  JSONObject forward=new JSONObject().put("id_str","3").put("orig",row);data.put("items",new JSONArray().put(forward));check(CreatorModels.dynamics(data,"").rows.get(0).text.contains("转发")&&CreatorModels.dynamics(data,"").rows.get(0).images.size()==1,"forwarded text and images retained");
  data.put("has_more",true);bad=false;try{CreatorModels.dynamics(data,"next");}catch(Exception e){bad=true;}check(bad,"unchanged dynamic cursor rejected");
  System.out.println("PASS: "+checks+" creator parsing and controller edge cases");
 }
}
